[1] = {1, 1000, "Great\u{0020}Sin", 1, 900000, "Nevaeh", "0", "The\u{0020}largest\u{0020}Sin\u{0020}known\u{0020}to\u{0020}humanity,\u{0020}towering\u{0020}over\u{0020}1,000\u{0020}meters\u{0020}in\u{0020}height.\u{0020}Her\u{0020}upper\u{0020}body\u{0020}takes\u{0020}the\u{0020}form\u{0020}of\u{0020}an\u{0020}enchanting\u{0020}woman,\u{0020}while\u{0020}her\u{0020}lower\u{0020}half\u{0020}is\u{0020}that\u{0020}of\u{0020}a\u{0020}steel\u{0020}serpent.\u{0020}She\u{0020}commands\u{0020}lesser\u{0020}Sins\u{0020}and\u{0020}effortlessly\u{0020}controls\u{0020}the\u{0020}[Gate],\u{0020}with\u{0020}her\u{0020}mastery\u{0020}of\u{0020}Nimbus\u{0020}energy\u{0020}amplifying\u{0020}the\u{0020}threat\u{0020}she\u{0020}poses.", "1001", "石黑千寻", "zhufun", 100028, 1, "0", "The\u{0020}largest\u{0020}Sin\u{0020}known\u{0020}to\u{0020}humanity,\u{0020}towering\u{0020}over\u{0020}1,000\u{0020}meters\u{0020}in\u{0020}height.\u{0020}Her\u{0020}upper\u{0020}body\u{0020}takes\u{0020}the\u{0020}form\u{0020}of\u{0020}an\u{0020}enchanting\u{0020}woman,\u{0020}while\u{0020}her\u{0020}lower\u{0020}half\u{0020}is\u{0020}that\u{0020}of\u{0020}a\u{0020}steel\u{0020}serpent.\u{0020}She\u{0020}commands\u{0020}lesser\u{0020}Sins\u{0020}and\u{0020}effortlessly\u{0020}controls\u{0020}the\u{0020}[Gate],\u{0020}with\u{0020}her\u{0020}mastery\u{0020}of\u{0020}Nimbus\u{0020}energy\u{0020}amplifying\u{0020}the\u{0020}threat\u{0020}she\u{0020}poses.", 1, "0", "0", "逆爱", "逆爱", "人类已知的体型最大的原罪，有着超过1000米的体长。有着少女一般的美丽半身，而她的另一半身，则是完全由钢铁构成的蛇形尾。拥有着操纵低等原罪行动，控制【传送门】、以自己的想法自由操纵尼姆比斯能源的能力。"},
[2] = {2, 1000, "Great\u{0020}Sin", 2, 900003, "Envy", "0", "The\u{0020}second\u{0020}Major\u{0020}Sin,\u{0020}following\u{0020}\"Greed,\"\u{0020}to\u{0020}invade\u{0020}human\u{0020}cities.\u{0020}Emerging\u{0020}from\u{0020}the\u{0020}\"Saar\u{0020}Sea,\"\u{0020}she\u{0020}embodies\u{0020}a\u{0020}fusion\u{0020}of\u{0020}woman\u{0020}and\u{0020}oceanic\u{0020}creature,\u{0020}a\u{0020}form\u{0020}that\u{0020}grants\u{0020}her\u{0020}unparalleled\u{0020}prowess\u{0020}in\u{0020}aquatic\u{0020}combat.\u{0020}\"Envy\"\u{0020}wields\u{0020}a\u{0020}special\u{0020}ability\u{0020}known\u{0020}as\u{0020}[Cognitive\u{0020}Interference].", "1000", "渡辺はるか", "zhufun", 100329, 1, "0", "The\u{0020}second\u{0020}Great\u{0020}Sin,\u{0020}following\u{0020}\"Greed,\"\u{0020}to\u{0020}invade\u{0020}human\u{0020}cities.\u{0020}Emerging\u{0020}from\u{0020}the\u{0020}\"Saar\u{0020}Sea,\"\u{0020}she\u{0020}embodies\u{0020}a\u{0020}fusion\u{0020}of\u{0020}woman\u{0020}and\u{0020}oceanic\u{0020}creature,\u{0020}a\u{0020}form\u{0020}that\u{0020}grants\u{0020}her\u{0020}unparalleled\u{0020}prowess\u{0020}in\u{0020}aquatic\u{0020}combat.\u{0020}\"Envy\"\u{0020}wields\u{0020}a\u{0020}special\u{0020}ability\u{0020}known\u{0020}as\u{0020}[Cognitive\u{0020}Interference].", 1, "0", "0", "罪级", "嫉妒", "继“贪婪”之后，第二个出现并入侵人类城市的高等原罪。降生在【萨尔近海】中的她，身体有着海洋生物的特征，仿佛尚未完全进化成人类的人鱼一般，这些异于人类的身体结构让嫉妒在海中有着得天独厚的优势。嫉妒所拥有的特殊能力是【认知干扰】。"},
[3] = {3, 1000, "Great\u{0020}Sin", 3, 610000, "Greed", "0", "\"Greed\",\u{0020}the\u{0020}first\u{0020}Great\u{0020}Sin,\u{0020}boasts\u{0020}a\u{0020}colossal\u{0020}form\u{0020}that\u{0020}merges\u{0020}features\u{0020}of\u{0020}both\u{0020}a\u{0020}woman\u{0020}and\u{0020}a\u{0020}monstrous\u{0020}entity.\u{0020}With\u{0020}an\u{0020}appearance\u{0020}that\u{0020}closely\u{0020}mirrors\u{0020}the\u{0020}progenitor\u{0020}of\u{0020}The\u{0020}Sins,\u{0020}\"Niai\",\u{0020}\"Greed\"\u{0020}stands\u{0020}as\u{0020}a\u{0020}testament\u{0020}to\u{0020}the\u{0020}formidable\u{0020}nature\u{0020}of\u{0020}its\u{0020}kind.\u{0020}At\u{0020}the\u{0020}time\u{0020}of\u{0020}\"Greed\"'s\u{0020}emergence,\u{0020}humanity's\u{0020}understanding\u{0020}of\u{0020}the\u{0020}Great\u{0020}Sins\u{0020}was\u{0020}still\u{0020}in\u{0020}its\u{0020}infancy,\u{0020}and\u{0020}they\u{0020}knew\u{0020}only\u{0020}that\u{0020}Greed\u{0020}wielded\u{0020}\"spatial\"\u{0020}manipulation\u{0020}abilities.", "1000", "谷掛未森", "zhufun", 9898989, 0, "0", "\"Greed\",\u{0020}the\u{0020}first\u{0020}Great\u{0020}Sin,\u{0020}boasts\u{0020}a\u{0020}colossal\u{0020}form\u{0020}that\u{0020}merges\u{0020}features\u{0020}of\u{0020}both\u{0020}a\u{0020}woman\u{0020}and\u{0020}a\u{0020}monstrous\u{0020}entity.\u{0020}With\u{0020}an\u{0020}appearance\u{0020}that\u{0020}closely\u{0020}mirrors\u{0020}the\u{0020}progenitor\u{0020}of\u{0020}The\u{0020}Sins,\u{0020}\"Niai\",\u{0020}\"Greed\"\u{0020}stands\u{0020}as\u{0020}a\u{0020}testament\u{0020}to\u{0020}the\u{0020}formidable\u{0020}nature\u{0020}of\u{0020}its\u{0020}kind.\u{0020}At\u{0020}the\u{0020}time\u{0020}of\u{0020}\"Greed\"'s\u{0020}emergence,\u{0020}humanity's\u{0020}understanding\u{0020}of\u{0020}the\u{0020}Great\u{0020}Sins\u{0020}was\u{0020}still\u{0020}in\u{0020}its\u{0020}infancy,\u{0020}and\u{0020}they\u{0020}knew\u{0020}only\u{0020}that\u{0020}Greed\u{0020}wielded\u{0020}\"spatial\"\u{0020}manipulation\u{0020}abilities.", 1, "0", "0", "罪级", "贪婪", "作为最初的高等原罪，“贪婪”的外表与原罪之祖【逆爱】十分相似，尽管未及但同样庞大的身躯，半身为人类少女，半身为不可名状的怪物之躯，如果原罪之间存在遗传因子，那么“贪婪”无疑是最接近【逆爱】的高等原罪。因为“贪婪”出现时，人类缺乏对高等原罪的了解。关于“贪婪”的特殊能力，仅知道与【空间】有关。"},
[4] = {4, 1000, "Great\u{0020}Sin", 4, 610001, "Gluttony", "0", "The\u{0020}Great\u{0020}Sin\u{0020}\"Gluttony\"\u{0020}emerged\u{0020}in\u{0020}the\u{0020}Maya\u{0020}region,\u{0020}leading\u{0020}an\u{0020}assault\u{0020}that\u{0020}transformed\u{0020}the\u{0020}Maya\u{0020}capital\u{0020}into\u{0020}her\u{0020}own\u{0020}twisted\u{0020}paradise.\u{0020}The\u{0020}attack\u{0020}also\u{0020}resulted\u{0020}in\u{0020}the\u{0020}crash\u{0020}of\u{0020}the\u{0020}Maya\u{0020}Ark.\u{0020}\"Gluttony\"\u{0020}takes\u{0020}the\u{0020}form\u{0020}of\u{0020}a\u{0020}half-man,\u{0020}half-wolf\u{0020}beast,\u{0020}nearly\u{0020}100\u{0020}meters\u{0020}in\u{0020}length,\u{0020}with\u{0020}powerful\u{0020}limbs\u{0020}that\u{0020}ensure\u{0020}no\u{0020}prey\u{0020}escapes\u{0020}her\u{0020}relentless\u{0020}pursuit.\u{0020}Her\u{0020}special\u{0020}ability\u{0020}is\u{0020}[Cognitive\u{0020}Interference].", "1000", "？？？", "zhufun", 9898989, 0, "0", "The\u{0020}Great\u{0020}Sin\u{0020}\"Gluttony\"\u{0020}emerged\u{0020}in\u{0020}the\u{0020}Maya\u{0020}region,\u{0020}leading\u{0020}an\u{0020}assault\u{0020}that\u{0020}transformed\u{0020}the\u{0020}Maya\u{0020}capital\u{0020}into\u{0020}her\u{0020}own\u{0020}twisted\u{0020}paradise.\u{0020}The\u{0020}attack\u{0020}also\u{0020}resulted\u{0020}in\u{0020}the\u{0020}crash\u{0020}of\u{0020}the\u{0020}Maya\u{0020}Ark.\u{0020}\"Gluttony\"\u{0020}takes\u{0020}the\u{0020}form\u{0020}of\u{0020}a\u{0020}half-man,\u{0020}half-wolf\u{0020}beast,\u{0020}nearly\u{0020}100\u{0020}meters\u{0020}in\u{0020}length,\u{0020}with\u{0020}powerful\u{0020}limbs\u{0020}that\u{0020}ensure\u{0020}no\u{0020}prey\u{0020}escapes\u{0020}her\u{0020}relentless\u{0020}pursuit.\u{0020}Her\u{0020}special\u{0020}ability\u{0020}is\u{0020}[Cognitive\u{0020}Interference].", 1, "0", "0", "罪级", "暴食", "出现在玛雅地区的高等原罪。由它主导的袭击使得【玛雅首都】沦为原罪的天堂，玛雅方舟也在原罪的冲击下坠毁。外观上，高等原罪“暴食”就像是一个半人半狼的猛兽，身长接近百米，它强壮的四肢为它的狩猎提供了绝佳的保证，没有人能从她的追击下逃过一命。暴食所拥有的特殊能力是【认知干扰】。"},
[5] = {5, 1000, "Great\u{0020}Sin", 5, 610002, "Lust", "0", "The\u{0020}Twin\u{0020}Maidens,\u{0020}also\u{0020}known\u{0020}as\u{0020}\"Lust,\"\u{0020}are\u{0020}twin\u{0020}beings\u{0020}of\u{0020}human-like\u{0020}height,\u{0020}making\u{0020}them\u{0020}the\u{0020}most\u{0020}similar\u{0020}to\u{0020}humans\u{0020}among\u{0020}the\u{0020}Great\u{0020}Sins.\u{0020}Unlike\u{0020}others\u{0020}of\u{0020}their\u{0020}kind,\u{0020}they\u{0020}do\u{0020}not\u{0020}display\u{0020}overt\u{0020}aggression\u{0020}toward\u{0020}humanity.", "1000", "福山あさき", "zhufun", 9898989, 0, "0", "The\u{0020}Twin\u{0020}Maidens,\u{0020}also\u{0020}known\u{0020}as\u{0020}\"Lust,\"\u{0020}are\u{0020}twin\u{0020}beings\u{0020}of\u{0020}human-like\u{0020}height,\u{0020}making\u{0020}them\u{0020}the\u{0020}most\u{0020}similar\u{0020}to\u{0020}humans\u{0020}among\u{0020}the\u{0020}Great\u{0020}Sins.\u{0020}Unlike\u{0020}others\u{0020}of\u{0020}their\u{0020}kind,\u{0020}they\u{0020}do\u{0020}not\u{0020}display\u{0020}overt\u{0020}aggression\u{0020}toward\u{0020}humanity.", 1, "0", "0", "罪级", "色欲", "自称为“色欲”的双子少女，与其他原罪不同，双子的身高与寻常人类并无区别。作为最接近人类的高等原罪，她们没有表现出对人类的明显攻击性。"},
