[9] = {9, 2000, "Major\u{0020}Sin", 1, 900001, "Sobek", "0", "A\u{0020}colossus\u{0020}nearly\u{0020}100\u{0020}meters\u{0020}tall,\u{0020}Sobek\u{0020}has\u{0020}repeatedly\u{0020}emerged\u{0020}on\u{0020}the\u{0020}front\u{0020}lines\u{0020}of\u{0020}human\u{0020}invasions,\u{0020}relentlessly\u{0020}crushing\u{0020}crews\u{0020}with\u{0020}devastating\u{0020}force.\u{0020}It\u{0020}embodies\u{0020}destruction\u{0020}and\u{0020}disaster,\u{0020}instilling\u{0020}fear\u{0020}in\u{0020}all\u{0020}who\u{0020}bear\u{0020}witness\u{0020}to\u{0020}its\u{0020}terrifying\u{0020}presence.", "1004，1005，1007", "/", "/", 100131, 1, "icon_zhunzui", "A\u{0020}colossus\u{0020}nearly\u{0020}100\u{0020}meters\u{0020}tall,\u{0020}Sobek\u{0020}has\u{0020}repeatedly\u{0020}emerged\u{0020}on\u{0020}the\u{0020}front\u{0020}lines\u{0020}of\u{0020}human\u{0020}invasions,\u{0020}relentlessly\u{0020}crushing\u{0020}crews\u{0020}with\u{0020}devastating\u{0020}force.\u{0020}It\u{0020}embodies\u{0020}destruction\u{0020}and\u{0020}disaster,\u{0020}instilling\u{0020}fear\u{0020}in\u{0020}all\u{0020}who\u{0020}bear\u{0020}witness\u{0020}to\u{0020}its\u{0020}terrifying\u{0020}presence.", 1, "0", "0", "准罪级", "索贝克", "体型接近百米的庞然大物，索贝克曾经数次出现在入侵人类城市的正面战场上，一次又一次，不厌其烦地将人类的驾驶员部队击溃。它仿佛带来了破灭与灾厄的利刃能将恐惧注入到每一个目睹它身姿的人的心中。"},
[10] = {10, 2000, "Major\u{0020}Sin", 2, 900002, "Jormungand", "0", "Jormungand,\u{0020}who\u{0020}had\u{0020}been\u{0020}lurking\u{0020}in\u{0020}the\u{0020}waters\u{0020}surrounding\u{0020}the\u{0020}artificial\u{0020}island\u{0020}[Third\u{0020}Laboratory],\u{0020}absorbed\u{0020}a\u{0020}high\u{0020}concentration\u{0020}of\u{0020}Nimbus\u{0020}energy—energy\u{0020}that\u{0020}had\u{0020}failed\u{0020}to\u{0020}manifest\u{0020}the\u{0020}Great\u{0020}Sin\u{0020}\"Envy.\"\u{0020}Under\u{0020}its\u{0020}influence,\u{0020}Jormungand's\u{0020}body\u{0020}swelled\u{0020}to\u{0020}an\u{0020}abnormal\u{0020}size.", "1003，1006", "/", "/", 100233, 1, "icon_zhunzui", "Jormungand,\u{0020}who\u{0020}had\u{0020}been\u{0020}lurking\u{0020}in\u{0020}the\u{0020}waters\u{0020}surrounding\u{0020}the\u{0020}artificial\u{0020}island\u{0020}[Third\u{0020}Laboratory],\u{0020}absorbed\u{0020}a\u{0020}high\u{0020}concentration\u{0020}of\u{0020}Nimbus\u{0020}energy—energy\u{0020}that\u{0020}had\u{0020}failed\u{0020}to\u{0020}manifest\u{0020}the\u{0020}Great\u{0020}Sin\u{0020}\"Envy.\"\u{0020}Under\u{0020}its\u{0020}influence,\u{0020}Jormungand's\u{0020}body\u{0020}swelled\u{0020}to\u{0020}an\u{0020}abnormal\u{0020}size.", 1, "0", "0", "准罪级", "耶梦加得", "徘徊在人工岛屿【第三研究室】周围海域的耶梦加得，吸收了未能形成高等原罪“嫉妒”身躯的高浓度的尼姆比斯能，身躯在尼姆比斯能的作用下变得异常庞大。"},
