[25] = {25, 3000, "Sin", 35, 220013, "Pteron\u{0020}T-1", "0", "A\u{0020}gregarious\u{0020}Sin\u{0020}born\u{0020}from\u{0020}the\u{0020}night\u{0020}mist,\u{0020}it\u{0020}exhibits\u{0020}reduced\u{0020}aggression\u{0020}during\u{0020}daylight\u{0020}hours.", "1002", "/", "/", 100202, 1, "icon_δ", "A\u{0020}gregarious\u{0020}Sin\u{0020}born\u{0020}from\u{0020}the\u{0020}night\u{0020}mist,\u{0020}it\u{0020}exhibits\u{0020}reduced\u{0020}aggression\u{0020}during\u{0020}daylight\u{0020}hours.", 1, "0", "0", "仿生体δ级", "翼手级\u{0020}T-1α", "在黑夜的苍雾中诞生的小型原罪，在白天的攻击欲望会大幅度降低。为什么……明明是原罪，却保留着与外形相似的习性。"},
