[38] = {38, 3000, "Sin", 55, 210017, "Gilloid\u{0020}T-6β", "0", "A\u{0020}variant\u{0020}of\u{0020}[Gilloid\u{0020}T-6],\u{0020}this\u{0020}Sin\u{0020}focuses\u{0020}on\u{0020}a\u{0020}more\u{0020}deceptive\u{0020}approach.\u{0020}Although\u{0020}it\u{0020}shares\u{0020}the\u{0020}same\u{0020}characteristics\u{0020}and\u{0020}appearance\u{0020}as\u{0020}the\u{0020}original,\u{0020}it\u{0020}employs\u{0020}trickier\u{0020}tactics\u{0020}in\u{0020}battle.", "1002", "/", "/", 100228, 1, "icon_γ", "A\u{0020}variant\u{0020}of\u{0020}[Gilloid\u{0020}T-6],\u{0020}this\u{0020}Sin\u{0020}focuses\u{0020}on\u{0020}a\u{0020}more\u{0020}deceptive\u{0020}approach.\u{0020}Although\u{0020}it\u{0020}shares\u{0020}the\u{0020}same\u{0020}characteristics\u{0020}and\u{0020}appearance\u{0020}as\u{0020}the\u{0020}original,\u{0020}it\u{0020}employs\u{0020}trickier\u{0020}tactics\u{0020}in\u{0020}battle.", 1, "0", "0", "仿生体γ级", "拟鳃级\u{0020}T-5β", "与普通的【拟鳃级\u{0020}T-5α】为同位体，低等原罪。注意其二，此类原罪丧失了硅基病毒的致命性，但是更容易感染，能有效干扰驾驶员的判断，切勿长时间交战。"},
