[42] = {42, 3000, "Sin", 22, 210006, "Pincerfang\u{0020}T-1", "0", "This\u{0020}Sin,\u{0020}usually\u{0020}over\u{0020}30\u{0020}meters\u{0020}in\u{0020}length,\u{0020}poses\u{0020}a\u{0020}threat\u{0020}by\u{0020}destroying\u{0020}itself,\u{0020}impacting\u{0020}the\u{0020}battlefield.\u{0020}Exercise\u{0020}caution\u{0020}when\u{0020}engaging\u{0020}it.", "1002", "/", "/", 100113, 1, "icon_β", "This\u{0020}Sin,\u{0020}usually\u{0020}over\u{0020}30\u{0020}meters\u{0020}in\u{0020}length,\u{0020}poses\u{0020}a\u{0020}threat\u{0020}by\u{0020}destroying\u{0020}itself,\u{0020}impacting\u{0020}the\u{0020}battlefield.\u{0020}Exercise\u{0020}caution\u{0020}when\u{0020}engaging\u{0020}it.", 1, "0", "0", "仿生体β级", "拟虫级\u{0020}T-2α", "外表形似人类熟悉的节肢动物蜘蛛的低等原罪，体长通常在三十米以上。它们通常会以“传送门”的方式出现在战场的各个角落，并且以自爆的攻击方式结束自己的生命。"},
