[44] = {44, 3000, "Sin", 59, 200005, "Crawler\u{0020}T-1", "0", "With\u{0020}a\u{0020}length\u{0020}of\u{0020}around\u{0020}60\u{0020}meters,\u{0020}this\u{0020}Sin\u{0020}is\u{0020}best\u{0020}tackled\u{0020}by\u{0020}small\u{0020}squads,\u{0020}including\u{0020}at\u{0020}least\u{0020}one\u{0020}specialized\u{0020}assault\u{0020}driver.\u{0020}If\u{0020}necessary,\u{0020}deploy\u{0020}branch\u{0020}artillery\u{0020}for\u{0020}additional\u{0020}support.", "1002", "/", "/", 100308, 1, "icon_β", "With\u{0020}a\u{0020}length\u{0020}of\u{0020}around\u{0020}60\u{0020}meters,\u{0020}this\u{0020}Sin\u{0020}is\u{0020}best\u{0020}tackled\u{0020}by\u{0020}small\u{0020}squads,\u{0020}including\u{0020}at\u{0020}least\u{0020}one\u{0020}specialized\u{0020}assault\u{0020}driver.\u{0020}If\u{0020}necessary,\u{0020}deploy\u{0020}branch\u{0020}artillery\u{0020}for\u{0020}additional\u{0020}support.", 1, "0", "0", "仿生体β级", "拟虫级\u{0020}T-4α", "外表形似人类熟悉的动物甲虫，低等原罪，通常体长为六十米，建议以小队形式进行讨伐，并且至少配备一名对空专精的驾驶员，必要情况下，可以调用各支部的炮击。"},
[45] = {45, 3000, "Sin", 26, 220008, "Crawler\u{0020}T-1β", "0", "This\u{0020}[Crawler\u{0020}T-1]\u{0020}variant\u{0020}is\u{0020}highly\u{0020}aggressive,\u{0020}so\u{0020}prioritize\u{0020}destroying\u{0020}its\u{0020}fire\u{0020}output\u{0020}ports\u{0020}in\u{0020}encounters.", "1002", "/", "/", 100118, 1, "icon_β", "This\u{0020}[Crawler\u{0020}T-1]\u{0020}variant\u{0020}is\u{0020}highly\u{0020}aggressive,\u{0020}so\u{0020}prioritize\u{0020}destroying\u{0020}its\u{0020}fire\u{0020}output\u{0020}ports\u{0020}in\u{0020}encounters.", 1, "0", "0", "仿生体β级", "拟虫级\u{0020}T-4β", "有极强攻击欲望的原罪，通常体长为六十米，遭遇战时，请迅速破坏它的火力口径。与之前发现的畸变体又有所不同，科学官正在调查是什么原因导致的变化。"},
[46] = {46, 3000, "Sin", 29, 210008, "Crawler\u{0020}T-3", "0", "A\u{0020}cunning\u{0020}Sin,\u{0020}usually\u{0020}between\u{0020}30\u{0020}and\u{0020}40\u{0020}meters\u{0020}long,\u{0020}that\u{0020}hides\u{0020}its\u{0020}position\u{0020}well\u{0020}and\u{0020}strikes\u{0020}from\u{0020}the\u{0020}fog\u{0020}when\u{0020}its\u{0020}prey\u{0020}is\u{0020}most\u{0020}vulnerable.", "1002", "/", "/", 100121, 1, "icon_β", "A\u{0020}cunning\u{0020}Sin,\u{0020}usually\u{0020}between\u{0020}30\u{0020}and\u{0020}40\u{0020}meters\u{0020}long,\u{0020}that\u{0020}hides\u{0020}its\u{0020}position\u{0020}well\u{0020}and\u{0020}strikes\u{0020}from\u{0020}the\u{0020}fog\u{0020}when\u{0020}its\u{0020}prey\u{0020}is\u{0020}most\u{0020}vulnerable.", 1, "0", "0", "仿生体β级", "拟虫级\u{0020}T-5α", "外表形似人类熟悉的动物螳螂，低等原罪，体长通常在三十米至四十米之间。“宛如杀手一般的原罪”是对它最好的形容。它不会轻易在战场上暴露自己的位置，只会在最合适的时候从雾气中袭击那些未能察觉到它存在的猎物。"},
[47] = {47, 3000, "Sin", 15, 220014, "Crawler\u{0020}T-4", "0", "This\u{0020}Sin,\u{0020}typically\u{0020}between\u{0020}30\u{0020}and\u{0020}40\u{0020}meters\u{0020}long,\u{0020}tends\u{0020}to\u{0020}swarm\u{0020}in\u{0020}water.\u{0020}Despite\u{0020}its\u{0020}powerful\u{0020}attacks,\u{0020}it\u{0020}has\u{0020}weak\u{0020}defenses,\u{0020}so\u{0020}stay\u{0020}calm\u{0020}when\u{0020}encountering\u{0020}it.", "1002", "/", "/", 100108, 1, "icon_β", "This\u{0020}Sin,\u{0020}typically\u{0020}between\u{0020}30\u{0020}and\u{0020}40\u{0020}meters\u{0020}long,\u{0020}tends\u{0020}to\u{0020}swarm\u{0020}in\u{0020}water.\u{0020}Despite\u{0020}its\u{0020}powerful\u{0020}attacks,\u{0020}it\u{0020}has\u{0020}weak\u{0020}defenses,\u{0020}so\u{0020}stay\u{0020}calm\u{0020}when\u{0020}encountering\u{0020}it.", 1, "0", "0", "仿生体β级", "拟虫级\u{0020}T-6α", "拥有在深海的苍雾中群聚的习性，一般见不到，在近海战斗时，会随着苍雾的传送而出现。当其出现时切莫慌张，个体的威胁程度很低。"},
[48] = {48, 3000, "Sin", 45, 200006, "Crustacean\u{0020}T-1", "0", "Found\u{0020}mainly\u{0020}in\u{0020}coastal\u{0020}areas,\u{0020}this\u{0020}Sin\u{0020}exhibits\u{0020}both\u{0020}offensive\u{0020}and\u{0020}defensive\u{0020}traits,\u{0020}with\u{0020}significant\u{0020}size\u{0020}variations\u{0020}among\u{0020}individuals.\u{0020}Regular\u{0020}squads\u{0020}are\u{0020}advised\u{0020}against\u{0020}engaging\u{0020}it\u{0020}due\u{0020}to\u{0020}these\u{0020}challenges.", "1002", "/", "/", 100211, 1, "icon_β", "Found\u{0020}mainly\u{0020}in\u{0020}coastal\u{0020}areas,\u{0020}this\u{0020}Sin\u{0020}exhibits\u{0020}both\u{0020}offensive\u{0020}and\u{0020}defensive\u{0020}traits,\u{0020}with\u{0020}significant\u{0020}size\u{0020}variations\u{0020}among\u{0020}individuals.\u{0020}Regular\u{0020}squads\u{0020}are\u{0020}advised\u{0020}against\u{0020}engaging\u{0020}it\u{0020}due\u{0020}to\u{0020}these\u{0020}challenges.", 1, "0", "0", "仿生体β级", "节肢级\u{0020}T-1α", "外表形似人类熟悉的动物螃蟹，低等原罪，通常体长为六十米，目前观测到的最大个体为一百二十米，观测到此类个体时不建议常规小队讨伐，请上报各支部，调用特殊小队进行讨伐。"},
[49] = {49, 3000, "Sin", 34, 210005, "Crustacean\u{0020}T-2", "0", "This\u{0020}Sin\u{0020}is\u{0020}typically\u{0020}found\u{0020}in\u{0020}the\u{0020}water\u{0020}and\u{0020}ranges\u{0020}from\u{0020}20\u{0020}to\u{0020}50\u{0020}meters\u{0020}in\u{0020}length.\u{0020}While\u{0020}it\u{0020}is\u{0020}formidable\u{0020}in\u{0020}its\u{0020}aquatic\u{0020}environment,\u{0020}luring\u{0020}it\u{0020}to\u{0020}the\u{0020}shore\u{0020}will\u{0020}significantly\u{0020}ease\u{0020}the\u{0020}fight.", "1002", "/", "/", 100202, 1, "icon_β", "This\u{0020}Sin\u{0020}is\u{0020}typically\u{0020}found\u{0020}in\u{0020}the\u{0020}water\u{0020}and\u{0020}ranges\u{0020}from\u{0020}20\u{0020}to\u{0020}50\u{0020}meters\u{0020}in\u{0020}length.\u{0020}While\u{0020}it\u{0020}is\u{0020}formidable\u{0020}in\u{0020}its\u{0020}aquatic\u{0020}environment,\u{0020}luring\u{0020}it\u{0020}to\u{0020}the\u{0020}shore\u{0020}will\u{0020}significantly\u{0020}ease\u{0020}the\u{0020}fight.", 1, "0", "0", "仿生体β级", "节肢级\u{0020}T-2α", "只在水中出没的低等原罪，体型在四十米到五十米，在水环境下作战时需要至少2队以上的常规小队才能将其讨伐。"},
[50] = {50, 3000, "Sin", 23, 210009, "Crustacean\u{0020}T-3", "0", "This\u{0020}Sin,\u{0020}almost\u{0020}exclusively\u{0020}found\u{0020}in\u{0020}the\u{0020}deep\u{0020}sea,\u{0020}has\u{0020}exceptionally\u{0020}strong\u{0020}armor\u{0020}capable\u{0020}of\u{0020}withstanding\u{0020}the\u{0020}immense\u{0020}pressure\u{0020}of\u{0020}deep-sea\u{0020}environments.\u{0020}Its\u{0020}resilience\u{0020}once\u{0020}caused\u{0020}significant\u{0020}disruptions\u{0020}to\u{0020}the\u{0020}construction\u{0020}of\u{0020}the\u{0020}[Third\u{0020}Laboratory].", "1002", "/", "/", 100117, 1, "icon_β", "This\u{0020}Sin,\u{0020}almost\u{0020}exclusively\u{0020}found\u{0020}in\u{0020}the\u{0020}deep\u{0020}sea,\u{0020}has\u{0020}exceptionally\u{0020}strong\u{0020}armor\u{0020}capable\u{0020}of\u{0020}withstanding\u{0020}the\u{0020}immense\u{0020}pressure\u{0020}of\u{0020}deep-sea\u{0020}environments.\u{0020}Its\u{0020}resilience\u{0020}once\u{0020}caused\u{0020}significant\u{0020}disruptions\u{0020}to\u{0020}the\u{0020}construction\u{0020}of\u{0020}the\u{0020}[Third\u{0020}Laboratory].", 1, "0", "0", "仿生体β级", "节肢级\u{0020}T-3α", "深海处才会出现的低等原罪，在建设第三研究院时对施工人员造成了很大的干扰。偶尔会来到浅海区。"},
[51] = {51, 3000, "Sin", 30, 210015, "Crustacean\u{0020}T-3β", "0", "A\u{0020}variant\u{0020}of\u{0020}[Crustacean\u{0020}T-3],\u{0020}this\u{0020}Sin\u{0020}boasts\u{0020}extremely\u{0020}resilient\u{0020}defenses.\u{0020}Ensure\u{0020}you\u{0020}have\u{0020}a\u{0020}well-thought-out\u{0020}strategy\u{0020}before\u{0020}engaging\u{0020}it.", "1002", "/", "/", 100121, 1, "icon_β", "A\u{0020}variant\u{0020}of\u{0020}[Crustacean\u{0020}T-3],\u{0020}this\u{0020}Sin\u{0020}boasts\u{0020}extremely\u{0020}resilient\u{0020}defenses.\u{0020}Ensure\u{0020}you\u{0020}have\u{0020}a\u{0020}well-thought-out\u{0020}strategy\u{0020}before\u{0020}engaging\u{0020}it.", 1, "0", "0", "仿生体β级", "节肢级\u{0020}T-3β", "与普通的【节肢级\u{0020}T-3α】为同位体，低等原罪。第三研究室建成后，开始在研究室周边出现。"},
