[54] = {54, 3000, "Sin", 32, 200010, "Pincerfang\u{0020}T-2β", "0", "This\u{0020}variant\u{0020}of\u{0020}[Pincerfang\u{0020}T-2]\u{0020}is\u{0020}a\u{0020}reckless\u{0020}monster\u{0020}that\u{0020}will\u{0020}self-destruct\u{0020}and\u{0020}perish\u{0020}along\u{0020}with\u{0020}its\u{0020}target\u{0020}if\u{0020}necessary.", "1002", "/", "/", 100122, 1, "icon_β", "This\u{0020}variant\u{0020}of\u{0020}[Pincerfang\u{0020}T-2]\u{0020}is\u{0020}a\u{0020}reckless\u{0020}monster\u{0020}that\u{0020}will\u{0020}self-destruct\u{0020}and\u{0020}perish\u{0020}along\u{0020}with\u{0020}its\u{0020}target\u{0020}if\u{0020}necessary.", 1, "0", "0", "仿生体β级", "节肢级\u{0020}T-6α", "外表形似蝎子的低等原罪，体型三十米左右。是不顾一切的杀戮机器，必要时会选择自爆来与敌人同归于尽。"},
